// Worker entry (wrangler.jsonc "main"): the OpenNext app, plus the cron triggers (render sweep, plan sync, retention,
// owner alerts every 5 minutes; the owner's daily digest at 07:00 UTC).
// `.open-next/worker.js` is generated by `npm run cf:build`; this file only wraps it (OpenNext "custom worker").
import handler from "./.open-next/worker.js";

/** The daily digest's cron expression; must match the second entry in wrangler.jsonc "triggers.crons". */
const DAILY_CRON = "0 7 * * *";

/** Where the sweep runs as. Webhook URLs minted by a sweep-time auto-retry use this origin. */
const DEFAULT_ORIGIN = "https://valora3d.com";

const worker = {
  fetch: handler.fetch,

  /**
   * Every few minutes (wrangler.jsonc "triggers.crons"): re-poll render jobs nobody has heard from, so a lost
   * RunPod webhook or a dropped submission still ends in a finished job or a refund; sync plans whose paid
   * period ended (sync_expired_plans); delete render outputs and models past their plan's retention. Goes
   * through the app's own route so the sweep uses the same code, env and secrets as the webhook.
   */
  async scheduled(controller, env, ctx) {
    const secret = env.CRON_SECRET;
    if (!secret) return;
    const origin = env.SITE_ORIGIN || DEFAULT_ORIGIN;
    const call = (path, name) =>
      Promise.resolve(
        handler.fetch(new Request(`${origin}${path}`, { method: "POST", headers: { Authorization: `Bearer ${secret}` } }), env, ctx),
      ).then(
        (res) => {
          if (!res.ok) console.error(`[cron] ${name} answered ${res.status}`);
        },
        () => console.error(`[cron] ${name} threw`),
      );
    // DAILY_CRON (wrangler.jsonc "triggers.crons"): the owner's daily digest. Every other tick: the sweep, then the
    // owner alert check (after the sweep, so it sees the jobs the sweep just finished).
    if (controller?.cron === DAILY_CRON) {
      ctx.waitUntil(call("/api/ops/digest", "digest"));
      return;
    }
    ctx.waitUntil(call("/api/renders/sweep", "sweep").then(() => call("/api/ops/alerts", "alerts")));
  },
};

export default worker;
